import { useEffect } from "react";
import "./MastHead.scss";

const SCRIPT_ID = "mpa-ds-masthead-script";
const SCRIPT_SRC = "https://cdn.jsdelivr.net/npm/@govtechsg/sgds-web-component/Masthead/index.js";

export const Masthead = (): JSX.Element => {
    useEffect(() => {
        if (!doAssetsExist()) {
            addAssets();
        }
    }, []);

    const doAssetsExist = () => {
        return document.getElementById(SCRIPT_ID);
    };

    const addAssets = () => {
        if (!document.getElementById(SCRIPT_ID)) {
          const script = document.createElement("script");
          script.id = SCRIPT_ID;
          script.type = "module";
          script.src = SCRIPT_SRC;
          document.head.appendChild(script);
        }
      };

    const createContent = () => {
        return { __html: "<sgds-masthead></sgds-masthead>" };
    };

    return <div className="wrapper" dangerouslySetInnerHTML={createContent()} />;
};